mapper.select:
SELECT d.id, d.device_code, d.device_name, d.device_type, d.manufacturer, d.model, d.ip_address, d.port, d.location, d.location_desc, d.water_area_id, d.status, d.last_heartbeat, d.extra_config, d.created_at, d.updated_at, d.deleted, w.name AS water_area_name FROM device d LEFT JOIN water_area w ON d.water_area_id = w.id WHERE d.deleted = 0
AND (d.device_name LIKE CONCAT('%', #{keyword}, '%') OR d.device_code LIKE CONCAT('%', #{keyword}, '%'))
AND d.device_type = #{type}
AND d.water_area_id = #{waterAreaId}
